    },
    {
      "kind": "activity",
      "template": "randomSimulation",
      "content": "{\"template\":\"randomSimulation\",\"prompt\":\"Guess, then run many batches of 100 seeds from the same Pp × pp cross.\",\"fields\":{\"mode\":\"chance\",\"model\":{\"kind\":\"binomial\",\"probability\":0.5,\"trials\":100,\"hit\":{\"comparison\":\"exactly\",\"value\":50}},\"runs\":1000,\"trialLabel\":\"Seed with 1 in 2 chance of white\",\"hitLabel\":\"Exactly 50 white flowers\"},\"data\":{\"isExample\":true},\"check\":{\"kind\":\"choice\",\"question\":\"About how often will a batch have exactly 50 white flowers?\",\"options\":[{\"id\":\"eight\",\"text\":\"About 8% of the time\",\"value\":0.08,\"isCorrect\":true,\"reason\":\"You expect results near 50, but they can land on many different counts. Exactly 50 occurs about 8% of the time.\"},{\"id\":\"half\",\"text\":\"About 50% of the time\",\"value\":0.5,\"isCorrect\":false,\"reason\":\"You may use the chance for one seed as the chance of exactly 50 in a batch. Those are different events.\"},{\"id\":\"most\",\"text\":\"About 90% of the time\",\"value\":0.9,\"isCorrect\":false,\"reason\":\"You may expect most batches to land exactly on the prediction, but chance spreads the counts around 50.\"}]}}"
    },
    {
      "kind": "check",
      "context": "In a Boise garden, Maya grows 100 seeds from a Pp × pp pea cross. They produce 47 plants with white flowers.",
      "question": "Was the 1 in 2 prediction wrong?",
      "options": [
        {
          "text": "No. Chance can put a batch near 50 without landing exactly on it.",
          "isCorrect": true,
          "reason": "You expect about 50 white flowers, but the actual count can vary from batch to batch.",
          "picture": null
        },
        {
          "text": "Yes. A 1 in 2 chance requires exactly 50 white flowers.",
          "isCorrect": false,
          "reason": "You are treating a chance for each seed as a guarantee for the whole batch. The count can vary.",
          "picture": null
        },
        {
          "text": "Yes. The result proves the chance was 47 in 100.",
          "isCorrect": false,
          "reason": "You are treating one batch's result as the exact chance. A batch can differ from its prediction by chance.",
          "picture": null
        }
      ],
      "image": null,
      "visual": null,
      "basis": null
    }
